/*
 Problem: 3536. Maximum Product of Two Digits
 Language: cpp
 Runtime: 0 ms (100.00%)
 Memory: 8.7 MB (65.96%)
 Tags: Math, Sorting
*/
class Solution {
public:
    int maxProduct(int n) {
        int max1 = 0, max2 = 0;

        while (n > 0) {
            int d = n % 10;
            if (d >= max1) {
                max2 = max1;
                max1 = d;
            } else if (d > max2) {
                max2 = d;
            }

            n /= 10;
        }

        return max1 * max2;
    }
};
